from __future__ import annotations

import typing
from dataclasses import dataclass
from typing import Any, Mapping, Tuple, Iterator

from morph_runtime.errors import Category, RuntimeFailure
from morph_runtime.http import HttpClient
from morph_runtime.paging import paginate
from morph_runtime.report import Outcome, RecordResult, RunReport
from morph_runtime.ops import FieldTransformError, MissingFieldError, Record

from integration.clients import source_client, target_client
from integration.transform import to_target

PAGE_SIZE: int = 100


def _fetch_page(page: int, page_size: int) -> Tuple[list[dict[str, Any]], int | None]:
    client: HttpClient = source_client()
    response: dict[str, Any] = client.request(
        method="GET",
        path="/customers",
        query={"page": page, "page_size": page_size},
    )
    items: list[dict[str, Any]] = response.get("items", [])
    total: int | None = response.get("total")
    return items, total


def _source_iter() -> Iterator[Record]:
    for raw in paginate(_fetch_page, page_size=PAGE_SIZE):
        # The runtime expects Record mapping of primitive values
        yield typing.cast(Record, raw)


def _target_get(user_id: str) -> dict[str, Any] | None:
    client: HttpClient = target_client()
    try:
        return client.request(method="GET", path=f"/users/{user_id}")
    except RuntimeFailure as exc:
        if exc.category is Category.NOT_FOUND:
            return None
        raise


def _target_create(payload: Mapping[str, Any]) -> dict[str, Any]:
    client: HttpClient = target_client()
    return client.request(method="POST", path="/users", body=payload)


def _target_update(user_id: str, payload: Mapping[str, Any]) -> dict[str, Any]:
    client: HttpClient = target_client()
    return client.request(method="PUT", path=f"/users/{user_id}", body=payload)


def _records_equal(src: Mapping[str, Any], tgt: Mapping[str, Any]) -> bool:
    # Compare only the fields produced by the mapping
    for key, value in src.items():
        if tgt.get(key) != value:
            return False
    return True


def run(keys: Tuple[str, ...]) -> RunReport:
    report: RunReport = RunReport(records=[], requests={})
    src_client: HttpClient = source_client()
    tgt_client: HttpClient = target_client()

    try:
        for src_rec in _source_iter():
            # Determine source identity
            src_key: str | None = src_rec.get("customer_id")
            if not isinstance(src_key, str):
                # No usable identity
                report.add(RecordResult(key=None, outcome=Outcome.NOT_SYNCABLE))
                continue

            try:
                transformed: dict[str, Any] = to_target(src_rec)
            except FieldTransformError as fte:
                # Missing required source field -> contract drift, abort whole run
                if isinstance(fte.__cause__, MissingFieldError):
                    report.fail_run(Category.CONTRACT_DRIFT, f"missing source field for mapping: {fte.field}")
                    return report
                # Other transformation error -> record as FAILED
                report.add(
                    RecordResult(
                        key=src_key,
                        outcome=Outcome.FAILED,
                        category=Category.VALIDATION,
                        detail=fte.detail,
                        fields=(fte.field,),
                    )
                )
                continue
            except Exception as exc:  # pragma: no cover
                report.add(
                    RecordResult(
                        key=src_key,
                        outcome=Outcome.FAILED,
                        category=Category.UNKNOWN,
                        detail=str(exc),
                    )
                )
                continue

            try:
                tgt_rec: dict[str, Any] | None = _target_get(src_key)
            except RuntimeFailure as exc:
                if exc.category is Category.AUTH:
                    report.fail_run(Category.AUTH, exc.detail)
                    return report
                # Other failures for this record are recorded as FAILED
                report.add(
                    RecordResult(
                        key=src_key,
                        outcome=Outcome.FAILED,
                        category=exc.category,
                        detail=exc.detail,
                        fields=exc.fields,
                    )
                )
                continue

            if tgt_rec is None:
                # Create new target record
                try:
                    _target_create(transformed)
                except RuntimeFailure as exc:
                    if exc.category is Category.AUTH:
                        report.fail_run(Category.AUTH, exc.detail)
                        return report
                    report.add(
                        RecordResult(
                            key=src_key,
                            outcome=Outcome.FAILED,
                            category=exc.category,
                            detail=exc.detail,
                            fields=exc.fields,
                        )
                    )
                    continue
                report.add(RecordResult(key=src_key, outcome=Outcome.CREATED))
                continue

            # Target exists – compare
            if _records_equal(transformed, tgt_rec):
                report.add(RecordResult(key=src_key, outcome=Outcome.UNCHANGED))
                continue

            # Update needed
            try:
                _target_update(src_key, transformed)
            except RuntimeFailure as exc:
                if exc.category is Category.AUTH:
                    report.fail_run(Category.AUTH, exc.detail)
                    return report
                report.add(
                    RecordResult(
                        key=src_key,
                        outcome=Outcome.FAILED,
                        category=exc.category,
                        detail=exc.detail,
                        fields=exc.fields,
                    )
                )
                continue
            report.add(RecordResult(key=src_key, outcome=Outcome.UPDATED))
    except RuntimeFailure as exc:
        # Errors while listing source records (e.g., auth)
        if exc.category is Category.AUTH:
            report.fail_run(Category.AUTH, exc.detail)
        else:
            report.fail_run(exc.category, exc.detail)
        return report

    # Populate request counts
    report.requests = {"source": src_client.requests_made, "target": tgt_client.requests_made}
    return report

