from __future__ import annotations

import typing
from dataclasses import dataclass
from typing import Any, Callable, Iterator, Mapping, Tuple

from morph_runtime.errors import Category, RuntimeFailure
from morph_runtime.http import HttpClient
from morph_runtime.ops import FieldTransformError, MissingFieldError, Record
from morph_runtime.paging import paginate
from morph_runtime.report import Outcome, RecordResult, RunReport

from integration.clients import source_client, target_client
from integration.transform import to_target


def _fetch_page(page: int, page_size: int) -> Tuple[list[dict[str, Any]], int | None]:
    """Fetch a page of customers from the source system.

    Returns a tuple of (items, total) where total may be None.
    """
    client: HttpClient = source_client()
    try:
        resp = client.request(
            method="GET",
            path="/customers",
            query={"page": page, "page_size": page_size},
        )
    except RuntimeFailure as exc:
        # Propagate authentication failures to the caller.
        raise exc
    # Expected shape: {"items": [...], "total": int, ...}
    items: list[dict[str, Any]] = resp.get("items", [])
    total: int | None = resp.get("total")
    return items, total


def _source_records() -> Iterator[dict[str, Any]]:
    """Iterate over all source customer records using pagination."""
    # Use a reasonable page size; the API does not specify limits.
    return paginate(_fetch_page, page_size=100)


def _lookup_target(user_id: Any) -> dict[str, Any] | None:
    """Return the existing target user record or None if not found."""
    client: HttpClient = target_client()
    try:
        return client.request(
            method="GET",
            path=f"/users/{user_id}",
        )
    except RuntimeFailure as exc:
        if exc.category is Category.NOT_FOUND:
            return None
        raise exc


def _compare_records(existing: Mapping[str, Any], transformed: Mapping[str, Any]) -> bool:
    """Return True if all fields in *transformed* match the existing target record."""
    for key, value in transformed.items():
        if existing.get(key) != value:
            return False
    return True


def run(keys: Tuple[str, ...]) -> RunReport:
    """Synchronise source customers to target users.

    The *keys* argument is ignored because the source supports listing.
    """
    report = RunReport(records=[], requests={})
    src_client = source_client()
    tgt_client = target_client()

    try:
        for src_rec in _source_records():
            # Determine the primary key for reporting – use source customer_id if present.
            src_key: str | None = src_rec.get("customer_id")
            try:
                transformed = to_target(src_rec)  # type: ignore[arg-type]
            except FieldTransformError as fte:
                # Missing source field is a contract drift – abort the whole run.
                if isinstance(fte.__cause__, MissingFieldError):
                    report.fail_run(Category.CONTRACT_DRIFT, f"Missing source field for record {src_key}")
                    return report
                # Other transformation errors are recorded as FAILED.
                report.add(
                    RecordResult(
                        key=src_key,
                        outcome=Outcome.FAILED,
                        category=Category.VALIDATION,
                        detail=str(fte),
                        fields=(fte.field,) if hasattr(fte, "field") else (),
                    )
                )
                continue

            # The target identifier is required for lookup and write operations.
            target_id = transformed.get("userId")
            if target_id is None:
                report.add(RecordResult(key=src_key, outcome=Outcome.NOT_SYNCABLE))
                continue

            try:
                existing = _lookup_target(target_id)
            except RuntimeFailure as exc:
                if exc.category is Category.AUTH:
                    report.fail_run(Category.AUTH, "Authentication failure on target system")
                    return report
                # Other failures for this record are recorded as FAILED.
                report.add(
                    RecordResult(
                        key=src_key,
                        outcome=Outcome.FAILED,
                        category=exc.category,
                        detail=exc.detail,
                    )
                )
                continue

            if existing is None:
                # Create new user.
                try:
                    tgt_client.request(method="POST", path="/users", body=transformed)
                except RuntimeFailure as exc:
                    if exc.category is Category.AUTH:
                        report.fail_run(Category.AUTH, "Authentication failure on target system")
                        return report
                    report.add(
                        RecordResult(
                            key=src_key,
                            outcome=Outcome.FAILED,
                            category=exc.category,
                            detail=exc.detail,
                        )
                    )
                    continue
                report.add(RecordResult(key=src_key, outcome=Outcome.CREATED))
            else:
                if _compare_records(existing, transformed):
                    report.add(RecordResult(key=src_key, outcome=Outcome.UNCHANGED))
                else:
                    try:
                        tgt_client.request(
                            method="PUT",
                            path=f"/users/{target_id}",
                            body=transformed,
                        )
                    except RuntimeFailure as exc:
                        if exc.category is Category.AUTH:
                            report.fail_run(Category.AUTH, "Authentication failure on target system")
                            return report
                        report.add(
                            RecordResult(
                                key=src_key,
                                outcome=Outcome.FAILED,
                                category=exc.category,
                                detail=exc.detail,
                            )
                        )
                        continue
                    report.add(RecordResult(key=src_key, outcome=Outcome.UPDATED))
    except RuntimeFailure as exc:
        # Errors while fetching source records.
        if exc.category is Category.AUTH:
            report.fail_run(Category.AUTH, "Authentication failure on source system")
        else:
            report.fail_run(exc.category, exc.detail)
        return report

    # Populate request counts.
    report.requests = {
        "source": src_client.requests_made,
        "target": tgt_client.requests_made,
    }
    return report
}

