from morph_runtime.report import Outcome, RecordResult, RunReport
from morph_runtime.ops import Record, FieldTransformError, MissingFieldError

from integration.clients import source_client, target_client
from integration.transform import to_target


def _fetch_source_record(client: HttpClient, user_id: str) -> Mapping[str, Any] | None:
    try:
        return client.request("GET", f"/users/{user_id}")
    except RuntimeFailure as exc:
        if exc.category is Category.NOT_FOUND:
            return None
        raise


def _fetch_target_record(client: HttpClient, customer_id: str) -> Mapping[str, Any] | None:
    try:
        return client.request("GET", f"/customers/{customer_id}")
    except RuntimeFailure as exc:
        if exc.category is Category.NOT_FOUND:
            return None
        raise


def _compare_target(record: Mapping[str, Any], transformed: Mapping[str, Any]) -> bool:
    """Return True if all writable target fields already match the transformed values."""
    # Fields that the API cannot write are listed in the compiled mapping.
    non_writable = {"customer_id", "created_at"}
    for key, value in transformed.items():
        if key in non_writable:
            continue
        if record.get(key) != value:
            return False
    return True


def run(keys: Tuple[str, ...]) -> RunReport:
    src = source_client()
    tgt = target_client()
    report = RunReport(records=[], requests={})

    # Helper to record a result
    def add_result(key: str | None, outcome: Outcome, category: Category | None = None,
                   detail: str = "", fields: Tuple[str, ...] = ()) -> None:
        report.add(RecordResult(key=key, outcome=outcome, category=category, detail=detail, fields=fields))

    # Process each supplied key (userId). If source cannot be listed we rely on keys.
    for user_id in keys:
        try:
            src_rec = _fetch_source_record(src, user_id)
        except RuntimeFailure as exc:
            if exc.category is Category.AUTH:
                report.fail_run(Category.AUTH, exc.detail)
                break
            add_result(user_id, Outcome.FAILED, exc.category, exc.detail)
            continue

        if src_rec is None:
            add_result(user_id, Outcome.NOT_SYNCABLE, Category.NOT_FOUND, "Source record not found")
            continue

        # Transform to target fields
        try:
            transformed = to_target(src_rec)  # type: ignore[arg-type]
        except FieldTransformError as exc:
            # Determine if missing source field
            if isinstance(exc.__cause__, MissingFieldError):
                add_result(user_id, Outcome.FAILED, Category.CONTRACT_DRIFT, exc.detail, (exc.field,))
                continue
            add_result(user_id, Outcome.FAILED, Category.VALIDATION, exc.detail, (exc.field,))
            continue
        except Exception as exc:  # unexpected
            add_result(user_id, Outcome.FAILED, Category.UNKNOWN, str(exc))
            continue

        # Identify target identity field
        customer_id = transformed.get("customer_id")
        if not isinstance(customer_id, str) or not customer_id:
            add_result(user_id, Outcome.NOT_SYNCABLE, Category.NOT_SYNCABLE, "Missing target identifier")
            continue

        # Fetch existing target record
        try:
            tgt_rec = _fetch_target_record(tgt, customer_id)
        except RuntimeFailure as exc:
            if exc.category is Category.AUTH:
                report.fail_run(Category.AUTH, exc.detail)
                break
            add_result(user_id, Outcome.FAILED, exc.category, exc.detail)
            continue

        if tgt_rec is None:
            # Create new record (exclude non‑writable fields)
            create_body = {k: v for k, v in transformed.items() if k not in {"customer_id", "created_at"}}
            try:
                tgt.request("POST", "/customers", body=create_body)
                add_result(user_id, Outcome.CREATED)
            except RuntimeFailure as exc:
                if exc.category is Category.AUTH:
                    report.fail_run(Category.AUTH, exc.detail)
                    break
                add_result(user_id, Outcome.FAILED, exc.category, exc.detail)
            continue

        # Record exists – decide if update needed
        if _compare_target(tgt_rec, transformed):
            add_result(user_id, Outcome.UNCHANGED)
            continue

        # Prepare patch payload (only changed writable fields)
        patch_body: dict[str, Any] = {}
        for key, new_val in transformed.items():
            if key in {"customer_id", "created_at"}:
                continue
            if tgt_rec.get(key) != new_val:
                patch_body[key] = new_val
        if not patch_body:
            add_result(user_id, Outcome.UNCHANGED)
            continue
        try:
            tgt.request("PATCH", f"/customers/{customer_id}", body=patch_body)
            add_result(user_id, Outcome.UPDATED)
        except RuntimeFailure as exc:
            if exc.category is Category.AUTH:
                report.fail_run(Category.AUTH, exc.detail)
                break
            add_result(user_id, Outcome.FAILED, exc.category, exc.detail)

    # Populate request counts
    report.requests = {
        "source": src.requests_made,
        "target": tgt.requests_made,
    }
    return report
}

