from morph_runtime.report import Outcome, RecordResult, RunReport
from morph_runtime.ops import Record, FieldTransformError, MissingFieldError

from integration.clients import source_client, target_client
from integration.transform import to_target


def _fetch_source_record(client: HttpClient, user_id: str) -> Mapping[str, Any] | None:
    try:
        return client.request("GET", f"/users/{user_id}")
    except RuntimeFailure as exc:
        if exc.category is Category.NOT_FOUND:
            return None
        raise


def _fetch_target_record(client: HttpClient, customer_id: str) -> Mapping[str, Any] | None:
    try:
        return client.request("GET", f"/customers/{customer_id}")
    except RuntimeFailure as exc:
        if exc.category is Category.NOT_FOUND:
            return None
        raise


def _compare_target(record: Mapping[str, Any], transformed: Mapping[str, Any]) -> bool:
    """Return True if all writable target fields already match the transformed values."""
    non_writable = {"customer_id", "created_at"}
    for key, value in transformed.items():
        if key in non_writable:
            continue
        if record.get(key) != value:
            return False
    return True


def run(keys: Tuple[str, ...]) -> RunReport:
    src = source_client()
    tgt = target_client()
    report = RunReport(records=[], requests={})

    def add_result(
        key: str | None,
        outcome: Outcome,
        category: Category | None = None,
        detail: str = "",
        fields: Tuple[str, ...] = (),
    ) -> None:
        report.add(RecordResult(key=key, outcome=outcome, category=category, detail=detail, fields=fields))

